#include <iostream>
#include <iomanip>

struct RolloutRiskModel {
    uint32_t totalFleet;
    double failureRate;
    double truckRollCostPerDevice;

    void compareStrategies() const {
        uint32_t failedAllAtOnce = (uint32_t)(totalFleet * failureRate);
        double costAllAtOnce = failedAllAtOnce * truckRollCostPerDevice;

        uint32_t canaryCohort = (uint32_t)(totalFleet * 0.01); // 1% Canary
        uint32_t failedCanary = (uint32_t)(canaryCohort * failureRate);
        double costCanary = failedCanary * truckRollCostPerDevice;

        std::cout << "--- DAY 49 PART 1: FLEET BLAST-RADIUS MITIGATION ---" << std::endl;
        std::cout << "Fleet Size: " << totalFleet << " devices | Defect Rate: " << failureRate * 100.0 << "%" << std::endl;
        std::cout << "All-At-Once Strategy: " << failedAllAtOnce << " bricked devices -> Cost: $" << std::fixed << std::setprecision(0) << costAllAtOnce << std::endl;
        std::cout << "1% Canary Strategy:   " << failedCanary << " impacted devices -> Cost: $" << costCanary << std::endl;
        std::cout << "Blast-Radius Reduction: $" << (costAllAtOnce - costCanary) << " SAVED! [CRITICAL]" << std::endl;
    }
};

int main() {
    RolloutRiskModel model{100000, 0.05, 250.00}; // 5% defect rate, $250 technician truck roll
    model.compareStrategies();
    return 0;
}

#include <iostream>
#include <vector>

enum class RolloutStage { CANARY_1_PCT, EARLY_ADOPTER_5_PCT, GENERAL_25_PCT, GENERAL_100_PCT };

struct CohortManager {
    RolloutStage currentStage;
    uint32_t deployedDevices;
    uint32_t totalFleet;

    void advanceRollout(bool healthCheckPassed) {
        std::cout << "--- DAY 49 PART 2: PROGRESSIVE FLEET ROLLOUT ---" << std::endl;
        if (!healthCheckPassed) {
            std::cout << "  [ROLLOUT-HALTED] Health anomaly detected! Freezing deployment at current stage! [SAFETY-HOLD]" << std::endl;
            return;
        }
        switch (currentStage) {
            case RolloutStage::CANARY_1_PCT:
                deployedDevices = (uint32_t)(totalFleet * 0.05);
                currentStage = RolloutStage::EARLY_ADOPTER_5_PCT;
                std::cout << "  [STAGE-ADVANCE] Canary soak passed! Advancing to Early Adopters (5% - " << deployedDevices << " devices)." << std::endl;
                break;
            case RolloutStage::EARLY_ADOPTER_5_PCT:
                deployedDevices = (uint32_t)(totalFleet * 0.25);
                currentStage = RolloutStage::GENERAL_25_PCT;
                std::cout << "  [STAGE-ADVANCE] Early adopter soak passed! Advancing to General Batch 1 (25% - " << deployedDevices << " devices)." << std::endl;
                break;
            case RolloutStage::GENERAL_25_PCT:
                deployedDevices = totalFleet;
                currentStage = RolloutStage::GENERAL_100_PCT;
                std::cout << "  [STAGE-ADVANCE] Advancing to 100% Full Fleet Deployment (" << deployedDevices << " devices)! [COMPLETE]" << std::endl;
                break;
            case RolloutStage::GENERAL_100_PCT:
                std::cout << "  [ROLLOUT-COMPLETE] Full fleet 100% updated and verified!" << std::endl;
                break;
        }
    }
};

int main() {
    CohortManager mgr{RolloutStage::CANARY_1_PCT, 1000, 100000};
    mgr.advanceRollout(true);
    mgr.advanceRollout(true);
    return 0;
}

#include <iostream>

struct FleetHealthMetrics {
    double crashRatePct;
    double disconnectRatePct;
    double batteryDrainRatePct;

    bool evaluateGate() const {
        std::cout << "--- DAY 49 PART 3: AUTOMATED TELEMETRY GATING ---" << std::endl;
        std::cout << "Telemetry Ingestion: Crash Rate = " << crashRatePct << "% (Limit: 0.05%)" << std::endl;
        std::cout << "Telemetry Ingestion: Disconnect Rate = " << disconnectRatePct << "% (Limit: 1.0%)" << std::endl;
        std::cout << "Telemetry Ingestion: Battery Drain Delta = " << batteryDrainRatePct << "% (Limit: 5.0%)" << std::endl;

        if (crashRatePct > 0.05) {
            std::cout << "  [GATE-TRIPPED] Crash rate breached threshold! Rollout FROZEN! [ABORT]" << std::endl;
            return false;
        }
        if (disconnectRatePct > 1.0) {
            std::cout << "  [GATE-TRIPPED] Disconnect rate breached threshold! Rollout FROZEN! [ABORT]" << std::endl;
            return false;
        }
        if (batteryDrainRatePct > 5.0) {
            std::cout << "  [GATE-TRIPPED] Battery drain excessive! Rollout FROZEN! [ABORT]" << std::endl;
            return false;
        }
        std::cout << "  [GATE-CLEAR] All fleet telemetry health gates verified within tolerance! [PASS]" << std::endl;
        return true;
    }
};

int main() {
    FleetHealthMetrics metrics{0.12, 0.4, 2.1}; // 0.12% crash rate exceeds 0.05% limit
    metrics.evaluateGate();
    return 0;
}

#include <iostream>

enum class DeviceFOTAState { DOWNLOADING, PENDING_REBOOT, TRIAL_MODE, NORMAL };

struct EmergencyAbortHandler {
    DeviceFOTAState currentState;

    void handleAbortSignal() {
        std::cout << "--- DAY 49 PART 4: EMERGENCY FLEET ABORT PROTOCOL ---" << std::endl;
        std::cout << "[ABORT-SIGNAL] Emergency Rollout Abort received from cloud broker!" << std::endl;
        switch (currentState) {
            case DeviceFOTAState::DOWNLOADING:
                std::cout << "  [ACTION] Terminating active download socket. Purging partial Slot 1! [CLEAN]" << std::endl;
                break;
            case DeviceFOTAState::PENDING_REBOOT:
                std::cout << "  [ACTION] Canceling pending reboot flag. Discarding candidate image! [SAFE]" << std::endl;
                break;
            case DeviceFOTAState::TRIAL_MODE:
                std::cout << "  [ACTION] Device in trial mode! Canceling confirmation. Triggering rollback reboot! [REVERT]" << std::endl;
                break;
            case DeviceFOTAState::NORMAL:
                std::cout << "  [ACTION] Device on baseline firmware. Update offer revoked. [NO-OP]" << std::endl;
                break;
        }
    }
};

int main() {
    EmergencyAbortHandler handler{DeviceFOTAState::TRIAL_MODE};
    handler.handleAbortSignal();
    return 0;
}

